const i = $input.first().json;
const esc = (v) => String(v ?? '').replace(/'/g, "''");
const wa = String(i.whatsapp || '').replace(/[^0-9A-Za-z+@._-]/g, '');
const motivo = String(i.motivo || 'Sin motivo indicado').trim().slice(0, 500);
const nombre = String(i.nombre || '').trim();

const query = `WITH upd AS (
  UPDATE leads SET
    notas = COALESCE(notas || chr(10), '') || '[Pidió contacto con Fla ' || to_char(NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires', 'DD/MM HH24:MI') || '] ${esc(motivo)}',
    ultimo_contacto = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
  WHERE whatsapp = '${esc(wa)}'
  RETURNING id, nombre, lead_tipo, estado
)
SELECT
  (SELECT valor FROM academia_config WHERE clave = 'telegram_chat_id_avisos') AS chat_id,
  (SELECT id FROM upd) AS lead_id,
  (SELECT nombre FROM upd) AS lead_nombre,
  (SELECT lead_tipo FROM upd) AS lead_tipo,
  (SELECT estado FROM upd) AS lead_estado;`;

return [{ json: { query, whatsapp: wa, motivo, nombre } }];

const r = $input.first().json;
const base = $('Armar consulta').first().json;
const h = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const nombre = r.lead_nombre || base.nombre || 'Sin nombre';
const lineas = ['🔔 <b>Un lead necesita a Fla</b>', '', `👤 ${h(nombre)}`, `📱 ${h(base.whatsapp)}`];
if (r.lead_tipo) lineas.push(`🏷️ ${h(r.lead_tipo)}${r.lead_estado ? ' · ' + h(r.lead_estado) : ''}`);
lineas.push('', `💬 ${h(base.motivo)}`);

return [{ json: { chat_id: r.chat_id, texto: lineas.join('\n'), lead_id: r.lead_id } }];

const r = $input.first().json;
if (!r || r.error || r.ok === false) {
  return [{ json: { success: false, message: 'No se pudo avisar a Fla en este momento. Decile a la persona que Fla la va a contactar apenas pueda, sin dar una hora.' } }];
}
return [{ json: { success: true, message: 'Fla ya fue avisada por Telegram. Podés decirle a la persona que Fla la contacta en cuanto pueda (sin prometer hora ni medio).' } }];
